using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGlobals(); // DO NOT MODIFY THIS LINE

// The game's files are not on Steam for anonymous accounts; fetch the latest official server into this server's
// game files folder (the create task copies it into the new service from there).
var target = Path.Combine(ThisServer.Configuration.GameFilesPath, ThisGame.FileAndDirectoryConfig.AutoSetupFolderName);
var http = new HttpClient();
await InstallServer(http, await LatestServerZip(http), target);
// Shared body of the Terraria install/update scripts: the official dedicated server zip from terraria.org holds
// <version>/Windows, <version>/Linux and <version>/Mac; only this host's folder is extracted into the target.
async Task<string> LatestServerZip(HttpClient http)
{
    var names = JsonSerializer.Deserialize<string[]>(await http.GetStringAsync("https://terraria.org/api/get/dedicated-servers-names"));
    if (names == null || names.Length == 0) throw new Exception("terraria.org returned no dedicated server versions.");
    return names[0];
}

async Task InstallServer(HttpClient http, string zipName, string target)
{
    Directory.CreateDirectory(target);
    var zipPath = Path.Combine(target, zipName);
    using (var response = await http.GetAsync("https://terraria.org/api/download/pc-dedicated-server/" + zipName, HttpCompletionOption.ResponseHeadersRead, ThisCancellationToken))
    {
        response.EnsureSuccessStatusCode();
        using (var file = File.Create(zipPath)) await response.Content.CopyToAsync(file, ThisCancellationToken);
    }
    var osFolder = System.OperatingSystem.IsWindows() ? "/Windows/" : "/Linux/";
    var fullTarget = Path.GetFullPath(target) + Path.DirectorySeparatorChar;
    var extracted = 0;
    using (var archive = ZipFile.OpenRead(zipPath))
    {
        foreach (var entry in archive.Entries)
        {
            var name = entry.FullName.Replace('\\', '/');
            var at = name.IndexOf(osFolder, StringComparison.OrdinalIgnoreCase);
            if (at < 0 || name.EndsWith("/")) continue;
            var relative = name.Substring(at + osFolder.Length);
            // The zip's sample serverconfig.txt is skipped: TCAdmin writes the service's own one from the config template,
            // and extracting the sample would overwrite the customer's settings on an update (and, copied from the game
            // files folder on Windows, it keeps that folder's read-only ACL, so the panel cannot save it).
            if (string.Equals(relative, "serverconfig.txt", StringComparison.OrdinalIgnoreCase)) continue;
            var destination = Path.GetFullPath(Path.Combine(target, relative));
            if (!destination.StartsWith(fullTarget, StringComparison.Ordinal)) continue;
            Directory.CreateDirectory(Path.GetDirectoryName(destination));
            entry.ExtractToFile(destination, true);
            extracted++;
        }
    }
    File.Delete(zipPath);
    if (extracted == 0) throw new Exception(zipName + " has no " + osFolder.Trim('/') + " server files.");
    if (!System.OperatingSystem.IsWindows())
    {
        foreach (var exe in new[] { "TerrariaServer.bin.x86_64", "TerrariaServer" })
        {
            var path = Path.Combine(target, exe);
            if (File.Exists(path)) File.SetUnixFileMode(path, File.GetUnixFileMode(path) | UnixFileMode.UserExecute | UnixFileMode.GroupExecute | UnixFileMode.OtherExecute);
        }
    }
    File.WriteAllText(Path.Combine(target, "terraria-version.txt"), zipName);
    ScriptConsole.WriteLine((object)("Installed " + zipName + " (" + extracted + " files)."));
}

//refAssemblies: TCAdmin.Monitor.SDK.dll, System.IO.Compression.dll, System.IO.Compression.ZipFile.dll, System.Net.Http.dll, System.Text.Json.dll
using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Installs the newest official server over this service's files. Worlds, the config and the ban list are not in
// the server zip, so they are kept. The server is stopped for the update and started again if it was running.
var root = (string)ThisService.RootDirectory;
var http = new HttpClient();
var latest = await LatestServerZip(http);
var versionFile = Path.Combine(root, "terraria-version.txt");
var installed = File.Exists(versionFile) ? File.ReadAllText(versionFile).Trim() : "";
if (installed == latest)
{
    ScriptConsole.WriteLine((object)("The server is up to date (" + latest + ")."));
    return;
}
ScriptConsole.WriteLine((object)("Updating " + (installed == "" ? "the server" : installed) + " to " + latest + "."));
var status = (await ServiceManagerService.GetServiceStatus(ThisService.ServiceId)).Status.ToString();
var wasRunning = status == "Started" || status == "Starting";
if (wasRunning)
{
    ScriptConsole.WriteLine((object)"Stopping the server.");
    await ServiceManagerService.StopService(ThisService.ServiceId);
}
await InstallServer(http, latest, root);
if (!System.OperatingSystem.IsWindows())
{
    // The script runs as the monitor; give the new files back to the service user.
    var credential = ServiceManagerService.GetServiceCredential(ThisService.ServiceId);
    Globals.OperatingSystem.SetDirectoryOwner(root, credential.Domain, credential.UserName, true);
}
if (wasRunning)
{
    ScriptConsole.WriteLine((object)"Starting the server.");
    await ServiceManagerService.StartService(ThisService.ServiceId);
}
