//refAssemblies: TCAdmin.Monitor.SDK.dll, System.Diagnostics.Process.dll, System.Net.Http.dll
using System;
using System.Diagnostics;
using System.IO;
using System.Net.Http;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

var root = (string)ThisService.RootDirectory;

// serverconfig.txt keeps worlds in "worlds". The script runs as the monitor, so on Linux the new folder is handed
// to the service user (a root-owned folder is hidden in the file manager and the server cannot write to it).
var worlds = Path.Combine(root, "worlds");
if (!Directory.Exists(worlds))
{
    Directory.CreateDirectory(worlds);
    if (!System.OperatingSystem.IsWindows())
    {
        var credential = ServiceManagerService.GetServiceCredential(ThisService.ServiceId);
        Globals.OperatingSystem.SetDirectoryOwner(worlds, credential.Domain, credential.UserName, true);
    }
}

// Windows: TerrariaServer.exe loads Microsoft.Xna.Framework 4.0 from the GAC and exits at once without it.
if (System.OperatingSystem.IsWindows())
{
    var gac = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows), "Microsoft.NET", "assembly", "GAC_32", "Microsoft.Xna.Framework");
    if (!Directory.Exists(gac))
    {
        ScriptConsole.WriteLine((object)"The Microsoft XNA Framework 4.0 Redistributable is missing on this host; installing it.");
        var msi = Path.Combine(Path.GetTempPath(), "xnafx40_redist.msi");
        var http = new HttpClient();
        File.WriteAllBytes(msi, await http.GetByteArrayAsync("https://download.microsoft.com/download/A/C/2/AC2C903B-E6E8-42C2-9FD7-BEBAC362A930/xnafx40_redist.msi"));
        using (var install = Process.Start(new ProcessStartInfo("msiexec.exe", new[] { "/i", msi, "/qn", "/norestart" }) { UseShellExecute = false }))
        {
            install.WaitForExit();
            File.Delete(msi);
            if (install.ExitCode != 0 && install.ExitCode != 3010) throw new Exception("Installing the XNA Framework 4.0 Redistributable failed (msiexec exit code " + install.ExitCode + ").");
        }
        ScriptConsole.WriteLine((object)"Installed the XNA Framework 4.0 Redistributable.");
    }
}

// Linux: the console runs in GNU screen. The server's console (Mono) asks its terminal for the cursor position; screen
// answers at once, while the panel's own terminal only answers when a browser console is open, and that late answer
// garbled the next command typed in the console. Install screen when the host does not have it.
if (System.OperatingSystem.IsLinux() && !Shell("command -v screen", out _))
{
    ScriptConsole.WriteLine((object)"GNU screen is missing on this host; installing it.");
    var installed =
        Shell("command -v apt-get && (DEBIAN_FRONTEND=noninteractive apt-get install -y screen || (apt-get update && DEBIAN_FRONTEND=noninteractive apt-get install -y screen))", out var aptLog)
        || Shell("command -v dnf && dnf install -y screen", out _)
        || Shell("command -v yum && yum install -y screen", out _);
    if (!installed) throw new Exception("GNU screen is missing and could not be installed. Install the screen package on this host. " + aptLog);
    ScriptConsole.WriteLine((object)"Installed GNU screen.");
}

bool Shell(string command, out string output)
{
    using (var process = Process.Start(new ProcessStartInfo("/bin/sh", new[] { "-c", command }) { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false }))
    {
        var stderr = process.StandardError.ReadToEndAsync();
        output = process.StandardOutput.ReadToEnd() + stderr.Result;
        process.WaitForExit();
        return process.ExitCode == 0;
    }
}

//refAssemblies: TCAdmin.Web.Shared.dll, System.Net.NetworkInformation.dll, System.Net.Primitives.dll
using System;
using System.Linq;
using System.Net;
using System.Net.NetworkInformation;
using TCAdmin.SDK.Hubs.Models.GameQuery;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Vanilla Terraria has no query protocol (qstat's "terraria" needs TShock's REST API), and every TCP connection is
// logged in the server console ("... is connecting"), so a probe every few seconds would flood it. The query runs on
// the monitor of the server that hosts the service, so it checks that the game port is listening on this machine.
// Player counts are not available without joining the game.
string address = Convert.ToString(Dynamic.Address);
if (string.IsNullOrEmpty(address)) address = ThisService.IPAddress;
// Terraria has one TCP port: the query port is only an alias of the game port, so the game port is checked (a query
// port left behind after the ports were edited would otherwise report a running server offline).
int port = ThisService.GamePort;
if (port <= 0) port = Convert.ToInt32(Dynamic.Port);

try
{
    IPAddress.TryParse(address, out var ip);
    var listening = IPGlobalProperties.GetIPGlobalProperties().GetActiveTcpListeners()
        .Any(l => l.Port == port && (ip == null || l.Address.Equals(ip) || l.Address.Equals(IPAddress.Any) || l.Address.Equals(IPAddress.IPv6Any)));
    Globals.ReturnValue = listening
        ? new GameQueryResponse
        {
            Success = true,
            Status = "online",
            Protocol = "custom_script",
            Address = address,
            Hostname = $"{address}:{port}",
            Name = ThisService.Name,
            GameType = "Terraria",
            Map = "",
            NumPlayers = 0,
            MaxPlayers = ThisService.Slots,
            NumSpectators = 0,
            MaxSpectators = 0,
            Retries = 0
        }
        : GameQueryResponse.DefaultOfflineResponse(address, "custom_script", $"Nothing is listening on {address}:{port}.");
}
catch (Exception ex)
{
    Globals.ReturnValue = GameQueryResponse.DefaultOfflineResponse(address, "custom_script", ex.Message);
}
